// Series data — But I can't just be a girl!.
// Generated by generate.js from results.csv: task "But I can't just be a girl!"
// (chain, ascii8, sensitive), budget 2^48 per search. One record
// per edge; its steps are every successively longer prefix match (first
// counter value per match length) of the one continuing grind. Every
// candidate message is base ‖ counter (64-bit little-endian; the counter is
// the "nonce" column in results.csv); every hash below was re-verified as
// SHA-256(base ‖ counter) at generation time.
(function () {
  const grinding = window.grinding = window.grinding || {};

  // base, word, matched chars, counter (the csv’s nonce), hash
  const rows = [
    ["But I can't be a girl!", "yes", 3, 3794991, "7965733b655bcfb8801ba83adb50817431bdb97701f7b0f3678226f319b7c516"],
    ["yes", "you", 1, 117, "79a48d84ae6b05616e72da505a105a6b7fb6df3c95e2cd5beca11e95f0cedff0"],
    ["yes", "you", 2, 257182, "796f6abdae77fd15bad7a3d9204ee65c6ab83ed30d2e3cc202f098f2f2322f32"],
    ["yes", "you", 3, 4197746, "796f75ee06044e3f02f3394bf6dc5a652bd98f84afe729e940c9ee8a3724f511"],
    ["you", "can", 1, 225, "632fdd9bdcef3e940d0ad4631345100af15cbfe0c62b21aaad1bc475c0a98ca5"],
    ["you", "can", 2, 24334, "636196ad4a2a18110577b7a5e7756a8ffd7331a50f75f3c4486a2149bf2ad66a"],
    ["you", "can", 3, 42940125, "63616e37cf8d8d29acd68db3c2b93fd266a3865d1fe554e03a8aa6b9571e429e"],
  ];

  const ascii8hex = s => [...s].map(c => c.charCodeAt(0).toString(16).padStart(2, "0")).join("");
  const edges = [];
  for (const [base, word] of rows)
    if (!edges.some(e => e[0] === base && e[1] === word)) edges.push([base, word]);

  grinding.series = {
    name: "But I can't just be a girl!",
    slug: "icjbag",
    base: "But I can't be a girl!",
    seedRow: false, // the base stays in the prose; no initial-value row
    topology: "chain",
    searchEncoding: "ascii8",
    caseMode: "sensitive",
    hashFunction: "SHA-256",
    budgetBits: 48,
    tokenId: 11, // position in the fixed edition; scripts/tokens.js agrees
    records: edges.map(([base, word], index) => {
      let prevNonce = 0;
      const steps = rows.filter(r => r[0] === base && r[1] === word)
        .map(([, , matchedChars, nonce, hash]) => {
          const st = { matchedChars, nonce, prevNonce, deltaAttempts: nonce - prevNonce, hash };
          prevNonce = nonce;
          return st;
        });
      const final = steps[steps.length - 1];
      return {
        index,
        word,
        base,
        plaintext: word, // as it appears in the csv
        totalChars: word.length,
        matchedChars: final.matchedChars, // < totalChars if the budget ran out
        full: final.matchedChars === word.length,
        encodedHex: ascii8hex(word),
        matchedNibbles: final.matchedChars * 2,
        nonce: final.nonce,
        attempts: final.nonce + 1,
        hash: final.hash,
        steps
      };
    }),
    words: ["yes","you","can"]
  };
})();
